/*
 * ============================================================================
 *  VS_Drop C3 — Wi-Fi файловый сервер на ESP32-C3 Super Mini
 * ============================================================================
 *
 *  Порт проекта:
 *  github.com/vlad-Stujhev1/ESP8266-Wi-Fi-file-server-with-SD-card-modern-web-UI
 *  (VS_Drop.cloud ESP8266 v5.0.0 "SD-Based Architecture") → ESP32-C3
 *
 *  Версия: 1.0.0-c3
 *
 *  АРХИТЕКТУРА (как в оригинале v5, упрощено по ТЗ):
 *
 *  SD-карта (FAT32):
 *  ├── index.html      ← веб-интерфейс (отдаётся на GET /)
 *  ├── style.css       ← стили (GET /style.css)
 *  ├── script.js       ← логика UI (GET /script.js)
 *  └── /data/          ← файлы пользователя (видны в UI, качаются через /download)
 *
 *  Маршруты:
 *  GET /               — index.html с SD
 *  GET /style.css      — стили с SD
 *  GET /script.js      — скрипт с SD
 *  GET /list           — JSON-список файлов в /data
 *  GET /download?file= — потоковое скачивание (порциями, без загрузки в RAM)
 *  GET /api/status     — JSON: Wi-Fi, SD, RAM, аптайм
 *
 *  Библиотеки: только встроенные в ядро esp32 (WiFi, WebServer, SPI, SD, ESPmDNS)
 *
 * ============================================================================
 */

#include <WiFi.h>
#include <WebServer.h>
#include <SPI.h>
#include <SD.h>
#include <ESPmDNS.h>

// ============================================================================
// ВЕРСИЯ
// ============================================================================

#define FIRMWARE_NAME    "VS_Drop C3"
#define FIRMWARE_VERSION "1.0.0"

// ============================================================================
// WI-FI — ЗАПОЛНИТЕ СВОИМИ ДАННЫМИ
// ============================================================================

// Режим STA (основной): подключение к домашней сети
#define WIFI_SSID   "YOUR_WIFI_SSID"     // ← имя вашей сети
#define WIFI_PASS   "YOUR_WIFI_PASSWORD" // ← пароль вашей сети
#define WIFI_TIMEOUT_MS 20000            // сколько ждать подключения, мс

// Резервный режим AP: если STA не удался, плата поднимает свою точку доступа
#define AP_SSID "VS_Drop-C3"   // имя точки доступа
#define AP_PASS "12345678"     // пароль (минимум 8 символов!)

// ============================================================================
// ПИНЫ (ESP32-C3 Super Mini + модуль MicroSD по SPI)
// ============================================================================

#define SD_CS    7   // Chip Select
#define SD_SCK   4   // Serial Clock
#define SD_MISO  5   // Master In Slave Out
#define SD_MOSI  6   // Master Out Slave In
// Внимание: питание модуля SD — строго 3.3V (НЕ 5V)!

// Светодиод на плате (Super Mini — GPIO8)
#define STATUS_LED 8

// ============================================================================
// ПОТОКОВАЯ ПЕРЕДАЧА (chunked streaming)
// ============================================================================

// Размер порции при отдаче файла. Файл НИКОГДА не загружается в RAM целиком:
// читаем по 4 КБ с SD и сразу отправляем клиенту (по ТЗ — не менее 1024 байт;
// 4096 оптимизировано под ESP32-C3: меньше обращений к TCP-стеку, выше скорость)
#define STREAM_CHUNK_SIZE 4096

// Ограничение на количество записей в /list (страховка от переполнения ответа)
#define LIST_MAX_ENTRIES 256

// Папка с пользовательскими файлами
#define PATH_DATA "/data"

// ============================================================================
// ГЛОБАЛЬНЫЕ ПЕРЕМЕННЫЕ
// ============================================================================

WebServer server(80);

bool sdInitialized   = false;
bool webFilesPresent = false;  // index.html найден на SD
bool wifiReady       = false;  // STA подключён или поднят AP
bool staMode         = true;   // true = STA, false = AP-fallback

// ============================================================================
// ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
// ============================================================================

String formatSize(uint64_t bytes) {
  if (bytes < 1024)               return String((uint32_t)bytes) + " Б";
  if (bytes < 1048576)            return String(bytes / 1024.0, 1) + " КБ";
  if (bytes < 1073741824)         return String(bytes / 1048576.0, 1) + " МБ";
  return String(bytes / 1073741824.0, 1) + " ГБ";
}

// Экранирование строки для JSON
String jsonEscape(const String& s) {
  String out;
  out.reserve(s.length() + 8);
  for (unsigned int i = 0; i < s.length(); i++) {
    char c = s.charAt(i);
    if (c == '"' || c == '\\') { out += '\\'; out += c; }
    else if (c == '\n') out += "\\n";
    else if (c == '\r') out += "\\r";
    else if (c == '\t') out += "\\t";
    else if ((uint8_t)c < 0x20) {
      char buf[8];
      snprintf(buf, sizeof(buf), "\\u%04x", (uint16_t)(uint8_t)c);
      out += buf;
    } else out += c;
  }
  return out;
}

// Базовое имя файла (без пути) — ESP32 file.name() может вернуть путь целиком
String baseName(const String& path) {
  int cut = path.lastIndexOf('/');
  return (cut >= 0) ? path.substring(cut + 1) : path;
}

// MIME-типы
String getMimeType(const String& path) {
  String p = path; p.toLowerCase();
  if (p.endsWith(".html") || p.endsWith(".htm")) return "text/html; charset=utf-8";
  if (p.endsWith(".css"))    return "text/css; charset=utf-8";
  if (p.endsWith(".js"))     return "application/javascript; charset=utf-8";
  if (p.endsWith(".json"))   return "application/json; charset=utf-8";
  if (p.endsWith(".png"))    return "image/png";
  if (p.endsWith(".jpg") || p.endsWith(".jpeg")) return "image/jpeg";
  if (p.endsWith(".gif"))    return "image/gif";
  if (p.endsWith(".bmp"))    return "image/bmp";
  if (p.endsWith(".webp"))   return "image/webp";
  if (p.endsWith(".ico"))    return "image/x-icon";
  if (p.endsWith(".svg"))    return "image/svg+xml";
  if (p.endsWith(".pdf"))    return "application/pdf";
  if (p.endsWith(".zip"))    return "application/zip";
  if (p.endsWith(".rar"))    return "application/vnd.rar";
  if (p.endsWith(".7z"))     return "application/x-7z-compressed";
  if (p.endsWith(".gz"))     return "application/gzip";
  if (p.endsWith(".txt"))    return "text/plain; charset=utf-8";
  if (p.endsWith(".xml"))    return "application/xml";
  if (p.endsWith(".mp3"))    return "audio/mpeg";
  if (p.endsWith(".wav"))    return "audio/wav";
  if (p.endsWith(".ogg"))    return "audio/ogg";
  if (p.endsWith(".flac"))   return "audio/flac";
  if (p.endsWith(".mp4"))    return "video/mp4";
  if (p.endsWith(".mkv"))    return "video/x-matroska";
  if (p.endsWith(".avi"))    return "video/x-msvideo";
  if (p.endsWith(".mov"))    return "video/quicktime";
  if (p.endsWith(".doc"))    return "application/msword";
  if (p.endsWith(".docx"))   return "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
  if (p.endsWith(".xls"))    return "application/vnd.ms-excel";
  if (p.endsWith(".xlsx"))   return "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
  if (p.endsWith(".apk"))    return "application/vnd.android.package-archive";
  if (p.endsWith(".bin") || p.endsWith(".img")) return "application/octet-stream";
  if (p.endsWith(".woff"))   return "font/woff";
  if (p.endsWith(".woff2"))  return "font/woff2";
  return "application/octet-stream";
}

// Защита от path traversal (как в оригинале)
bool isSafeFileName(const String& name) {
  if (name.length() == 0 || name.length() > 64) return false;
  if (name.indexOf('/') >= 0)   return false;   // слэши запрещены — только имя файла
  if (name.indexOf('\\') >= 0)  return false;
  if (name.indexOf("..") >= 0)  return false;
  if (name == "." )             return false;
  return true;
}

// ============================================================================
// SD-КАРТА
// ============================================================================

String sdTypeToString(sdcard_type_t t) {
  switch (t) {
    case CARD_MMC:  return "MMC";
    case CARD_SD:   return "SD";
    case CARD_SDHC: return "SDHC";
    case CARD_SDSC: return "SDSC";
    default:        return "UNKNOWN";
  }
}

bool initSDCard() {
  Serial.println(F("[SD] Инициализация..."));

  SPI.begin(SD_SCK, SD_MISO, SD_MOSI, SD_CS);

  // Пробуем на убывающих частотах: длинные провода Dupont не всегда тянут 16 МГц
  static const uint32_t speeds[] = { 16000000, 8000000, 4000000 };
  for (uint32_t freq : speeds) {
    if (SD.begin(SD_CS, SPI, freq)) {
      sdInitialized = true;
      Serial.printf("[SD] OK (SPI %u МГц, тип: %s, объём: %s)\n",
                    (unsigned)(freq / 1000000),
                    sdTypeToString(SD.cardType()).c_str(),
                    formatSize(SD.cardSize()).c_str());
      return true;
    }
    Serial.printf("[SD] Не удалось на %u МГц, пробую ниже...\n", (unsigned)(freq / 1000000));
    delay(50);
  }

  Serial.println(F("[SD] ОШИБКА: карта не найдена!"));
  Serial.println(F("[SD] Проверьте: питание 3.3V (не 5V!), провода CS=7 SCK=4 MOSI=6 MISO=5,"));
  Serial.println(F("[SD] формат карты FAT32, контакт в переходнике microSD."));
  return false;
}

void ensureDataFolder() {
  if (!sdInitialized) return;
  if (!SD.exists(PATH_DATA)) {
    if (SD.mkdir(PATH_DATA)) Serial.println(F("[SD] Создана папка /data"));
    else                      Serial.println(F("[SD] Не удалось создать /data"));
  }
  webFilesPresent = SD.exists("/index.html");
  if (!webFilesPresent) {
    Serial.println(F("[SD] ВНИМАНИЕ: /index.html не найден — будет показана встроенная страница"));
    Serial.println(F("[SD] Скопируйте на карту index.html, style.css, script.js (см. README)"));
  } else {
    Serial.println(F("[SD] Веб-интерфейс найден: /index.html"));
  }
}

// Отдача файла из корня SD со стримингом (для index/style/script)
bool serveWebFile(const char* sdPath, const char* urlPath, uint32_t cacheSec) {
  if (!sdInitialized || !SD.exists(sdPath)) return false;

  File file = SD.open(sdPath, FILE_READ);
  if (!file) return false;

  // streamFile читает с SD порциями и отправляет, не загружая файл в RAM
  server.sendHeader("Cache-Control", "max-age=" + String(cacheSec));
  server.streamFile(file, getMimeType(sdPath));
  file.close();

  Serial.printf("[WEB] %s → SD:%s\n", urlPath, sdPath);
  return true;
}

// ============================================================================
// ВСТРОЕННАЯ СТРАНИЦА (fallback — работает даже без SD-карты)
// ============================================================================

