// ============================================================================
// ОБРАБОТЧИКИ: ВЕБ-ИНТЕРФЕЙС
// ============================================================================

void handleRoot() {
  if (!serveWebFile("/index.html", "/", 60)) sendBuiltInPage();
}

void handleStyle() {
  if (!serveWebFile("/style.css", "/style.css", 300)) {
    server.send(404, "text/plain; charset=utf-8", "style.css не найден на SD-карте");
  }
}

void handleScript() {
  if (!serveWebFile("/script.js", "/script.js", 300)) {
    server.send(404, "text/plain; charset=utf-8", "script.js не найден на SD-карте");
  }
}

// ============================================================================
// API: /list — JSON-список файлов в /data
// ============================================================================

void handleList() {
  if (!sdInitialized) {
    server.send(503, "application/json; charset=utf-8",
                "{\"error\":\"SD not initialized\"}");
    return;
  }

  File root = SD.open(PATH_DATA, FILE_READ);
  if (!root || !root.isDirectory()) {
    if (root) root.close();
    server.send(200, "application/json; charset=utf-8", "[]");
    return;
  }

  String json = "[";
  int count = 0;
  bool first = true;

  File entry = root.openNextFile();
  while (entry && count < LIST_MAX_ENTRIES) {
    String name = baseName(String(entry.name()));

    if (!first) json += ",";
    first = false;

    json += "{\"name\":\"" + jsonEscape(name) + "\"";
    json += ",\"size\":" + String((uint32_t)entry.size());
    json += ",\"dir\":" + String(entry.isDirectory() ? "true" : "false") + "}";

    entry.close();
    entry = root.openNextFile();
    count++;
    yield();
  }
  if (entry) entry.close();
  root.close();

  json += "]";

  server.sendHeader("Cache-Control", "no-store");
  server.send(200, "application/json; charset=utf-8", json);
  Serial.printf("[WEB] /list → %d записей\n", count);
}

// ============================================================================
// API: /api/status — состояние устройства (для карточки в UI)
// ============================================================================

void handleStatus() {
  String json = "{";
  json += "\"name\":\"" FIRMWARE_NAME "\"";
  json += ",\"version\":\"" FIRMWARE_VERSION "\"";
  json += ",\"chip\":\"ESP32-C3\"";

  // Wi-Fi
  json += ",\"wifi\":{";
  json += "\"mode\":\"" + String(staMode ? "STA" : "AP") + "\"";
  json += ",\"ssid\":\"" + jsonEscape(staMode ? WIFI_SSID : AP_SSID) + "\"";
  json += ",\"ip\":\"" + (staMode ? WiFi.localIP().toString() : WiFi.softAPIP().toString()) + "\"";
  if (staMode) json += ",\"rssi\":" + String(WiFi.RSSI());
  json += "}";

  // SD
  json += ",\"sd\":{";
  json += "\"ok\":" + String(sdInitialized ? "true" : "false");
  if (sdInitialized) {
    json += ",\"type\":\"" + sdTypeToString(SD.cardType()) + "\"";
    json += ",\"sizeBytes\":" + String((uint32_t)(SD.totalBytes() & 0xFFFFFFFF));
    json += ",\"usedBytes\":" + String((uint32_t)(SD.usedBytes() & 0xFFFFFFFF));
    json += ",\"sizeMB\":" + String((uint32_t)(SD.totalBytes() / 1048576));
    json += ",\"usedMB\":" + String((uint32_t)(SD.usedBytes() / 1048576));
  }
  json += "}";

  // RAM
  json += ",\"heap\":{\"free\":" + String(ESP.getFreeHeap());
  json += ",\"min\":" + String(ESP.getMinFreeHeap()) + "}";

  // Аптайм
  json += ",\"uptimeSec\":" + String((uint32_t)(millis() / 1000));

  json += "}";

  server.sendHeader("Cache-Control", "no-store");
  server.send(200, "application/json; charset=utf-8", json);
}

// ============================================================================
// /download?file=ИМЯ — потоковое скачивание (chunked streaming)
// ============================================================================

void handleDownload() {
  if (!sdInitialized) {
    server.send(503, "text/plain; charset=utf-8", "SD-карта не инициализирована");
    return;
  }

  String name = server.arg("file");

  // Анти-траверсал: только простое имя файла, без путей
  if (!isSafeFileName(name)) {
    server.send(400, "text/plain; charset=utf-8", "Некорректное имя файла");
    return;
  }

  String path = String(PATH_DATA) + "/" + name;

  if (!SD.exists(path)) {
    server.send(404, "text/plain; charset=utf-8", "Файл не найден: " + name);
    return;
  }

  File file = SD.open(path, FILE_READ);
  if (!file || file.isDirectory()) {
    if (file) file.close();
    server.send(400, "text/plain; charset=utf-8", "Не удалось открыть файл");
    return;
  }

  // Имя без кавычек — для заголовка Content-Disposition
  String safeName = name;
  safeName.replace("\"", "");

  /*
   * ПОТОКОВАЯ ОТДАЧА (chunked streaming):
   *  - файл НЕ загружается в RAM целиком;
   *  - читаем с SD порциями по STREAM_CHUNK_SIZE байт и сразу отправляем;
   *  - Content-Length известен (размер файла) → браузер рисует прогресс-бар;
   *  - буфер один и тот же на всё время передачи.
   */
  const uint64_t fileSize = file.size();

  server.setContentLength((size_t)fileSize);
  server.sendHeader("Content-Disposition", "attachment; filename=\"" + safeName + "\"");
  server.send(200, getMimeType(path), "");

  static uint8_t buf[STREAM_CHUNK_SIZE];
  uint64_t sent = 0;
  const uint32_t t0 = millis();

  while (file.available()) {
    // Если клиент отключился — прекращаем, не молотим SD впустую
    if (!server.client().connected()) {
      Serial.printf("[DL] Клиент отключился: %s из %s\n",
                    formatSize(sent).c_str(), formatSize(fileSize).c_str());
      break;
    }

    size_t n = file.read(buf, sizeof(buf));
    if (n == 0) break;
    server.sendContent((const char*)buf, n);
    sent += n;
    yield();
  }
  file.close();

  Serial.printf("[DL] %s · %s · %.1f КБ/с\n",
                safeName.c_str(), formatSize(sent).c_str(),
                sent / 1024.0 / max(0.001f, (millis() - t0) / 1000.0f));
}

// ============================================================================
// WI-FI: STA → AP-fallback (как в ТЗ: основной STA, резерв — точка доступа)
// ============================================================================

bool connectWiFi() {
  Serial.printf("\n[WiFi] Подключение к «%s»", WIFI_SSID);

  WiFi.mode(WIFI_STA);
  WiFi.setAutoReconnect(true);
  WiFi.begin(WIFI_SSID, WIFI_PASS);

  const uint32_t t0 = millis();
  while (WiFi.status() != WL_CONNECTED) {
    delay(250);
    Serial.print('.');
    digitalWrite(STATUS_LED, !digitalRead(STATUS_LED)); // мигаем LED
    if (millis() - t0 > WIFI_TIMEOUT_MS) return false;
  }

  Serial.println();
  Serial.println(F("[WiFi] Подключено!"));
  Serial.printf("[WiFi] IP-адрес: %s  (RSSI: %d dBm)\n",
                WiFi.localIP().toString().c_str(), WiFi.RSSI());
  return true;
}

void startFallbackAP() {
  staMode = false;
  Serial.println(F("\n[WiFi] STA не удался — поднимаю точку доступа"));
  WiFi.mode(WIFI_AP);
  WiFi.softAP(AP_SSID, AP_PASS);

  Serial.printf("[WiFi] AP «%s» запущена, пароль: %s\n", AP_SSID, AP_PASS);
  Serial.printf("[WiFi] Подключитесь к сети и откройте http://%s\n",
                WiFi.softAPIP().toString().c_str());
}

// ============================================================================
// SETUP
// ============================================================================

void setup() {
  Serial.begin(115200);
  delay(1500);  // USB CDC на ESP32-C3 Super Mini нужно время подняться

  pinMode(STATUS_LED, OUTPUT);
  digitalWrite(STATUS_LED, LOW);

  Serial.println();
  Serial.println(F("========================================"));
  Serial.println(F("  VS_Drop C3 — Wi-Fi файловый сервер"));
  Serial.println(F("  Порт ESP8266 v5.0.0 → ESP32-C3"));
  Serial.println(F("  Версия: " FIRMWARE_VERSION));
  Serial.println(F("========================================"));

  // --- SD-карта ---
  sdInitialized = initSDCard();
  if (sdInitialized) ensureDataFolder();

  // --- Wi-Fi ---
  if (connectWiFi()) {
    wifiReady = true;
    digitalWrite(STATUS_LED, HIGH);
  } else {
    startFallbackAP();
    wifiReady = true;
    digitalWrite(STATUS_LED, HIGH);
  }

  // --- mDNS: http://vsdrop.local (работает в Safari/iOS; Android чаще нет) ---
  if (MDNS.begin("vsdrop")) {
    MDNS.addService("http", "tcp", 80);
    Serial.println(F("[DNS] Доступно по адресу http://vsdrop.local"));
  }

  // --- Маршруты ---
  server.on("/",           HTTP_GET, handleRoot);
  server.on("/index.html", HTTP_GET, handleRoot);
  server.on("/style.css",  HTTP_GET, handleStyle);
  server.on("/script.js",  HTTP_GET, handleScript);
  server.on("/list",       HTTP_GET, handleList);
  server.on("/api/status", HTTP_GET, handleStatus);
  server.on("/download",   HTTP_GET, handleDownload);

  server.onNotFound([]() {
    server.send(404, "text/plain; charset=utf-8", "404: не найдено");
  });

  server.begin();

  Serial.println();
  Serial.println(F("========================================"));
  Serial.println(F("  ГОТОВО"));
  Serial.println(F("========================================"));
  Serial.printf("  Web:       http://%s  (или http://vsdrop.local)\n",
                (staMode ? WiFi.localIP() : WiFi.softAPIP()).toString().c_str());
  Serial.println(F("  Файлы UI:  index.html, style.css, script.js → корень SD"));
  Serial.println(F("  Файлы:     /data на SD-карте"));
  Serial.println(F("  Скачивание: /download?file=ИМЯ (из /data)"));
  Serial.println(F("========================================"));
}

// ============================================================================
// LOOP
// ============================================================================

void loop() {
  server.handleClient();

  // Индикатор: LED горит при рабочем Wi-Fi; мигает при потере связи в STA
  if (staMode) {
    digitalWrite(STATUS_LED, WiFi.status() == WL_CONNECTED ? HIGH : (millis() % 500 < 250));
  }

  yield();
}
